spec.setup_code:
var c = null;
var seed = 11;
function rand() { seed = (seed * 1664525 + 1013904223) % 4294967296; return seed / 4294967296; }
function sat(x) { return x < 0 ? 0 : (x > 1 ? 1 : x); }
function sm(x) { x = sat(x); return x * x * (3 - 2 * x); }
function lerp(a, b, t) { return a + (b - a) * t; }
function h1(u) { return 0.66 + 0.05 * Math.sin(u * 5 + 1); }
function h2(u) { return 0.78 + 0.04 * Math.sin(u * 8 + 3); }

function sceneRGB(u, v) {
  var k = sat(v / 0.7);
  var r = lerp(60, 252, k), g = lerp(120, 196, k), b = lerp(215, 150, k);
  var dx = u - 0.68, dy = v - 0.3, d = Math.sqrt(dx * dx + dy * dy);
  if (d < 0.11) { r = 255; g = 222; b = 90; }
  else if (d < 0.2) { var q = (1 - (d - 0.11) / 0.09) * 0.5; r = lerp(r, 255, q); g = lerp(g, 225, q); b = lerp(b, 140, q); }
  if (v > h2(u)) { r = 34; g = 100; b = 76; }
  else if (v > h1(u)) { r = 82; g = 150; b = 98; }
  return [r, g, b];
}

// precomputed 32x32 "latent" colours: blurred, false-coloured, slightly noisy
var LAT = [];
for (var j = 0; j < 32; j++) {
  for (var i = 0; i < 32; i++) {
    var ar = 0, ag = 0, ab = 0;
    for (var k = 0; k < 5; k++) {
      var s = sceneRGB(sat((i + 0.5 + (rand() - 0.5) * 3) / 32), sat((j + 0.5 + (rand() - 0.5) * 3) / 32));
      ar += s[0] / 5; ag += s[1] / 5; ab += s[2] / 5;
    }
    var R = 0.55 * ag + 0.45 * ar + (rand() - 0.5) * 30;
    var G = 0.5 * ab + 0.3 * ar + 0.2 * ag + (rand() - 0.5) * 30;
    var B = 0.6 * ar + 0.4 * ab + (rand() - 0.5) * 30;
    LAT.push('rgb(' + Math.round(sat(R / 255) * 255) + ',' + Math.round(sat(G / 255) * 255) + ',' + Math.round(sat(B / 255) * 255) + ')');
  }
}

function txt(s, x, y, col, a, align, px, bold) {
  if (a <= 0.01) return;
  c.font = (bold ? 'bold ' : '') + (px || 12) + 'px sans-serif';
  c.globalAlpha = a; c.fillStyle = col; c.textAlign = align || 'center';
  c.fillText(s, x, y); c.globalAlpha = 1;
}

function wrap(s, maxW) {
  if (c.measureText(s).width <= maxW) return [s];
  var w = s.split(' '), best = [s], bd = 1e9;
  for (var i = 1; i < w.length; i++) {
    var a = w.slice(0, i).join(' '), b = w.slice(i).join(' ');
    var m = Math.max(c.measureText(a).width, c.measureText(b).width);
    if (m < bd) { bd = m; best = [a, b]; }
  }
  return best;
}

function drawImg(cx, cy, s, a) {
  if (a <= 0.01) return;
  var x = cx - s / 2, y = cy - s / 2;
  c.save(); c.globalAlpha = a;
  c.beginPath(); c.rect(x, y, s, s); c.clip();
  var gr = c.createLinearGradient(0, y, 0, y + s * 0.7);
  gr.addColorStop(0, 'rgb(60,120,215)'); gr.addColorStop(1, 'rgb(252,196,150)');
  c.fillStyle = gr; c.fillRect(x, y, s, s);
  c.fillStyle = 'rgba(255,225,140,0.45)';
  c.beginPath(); c.arc(x + 0.68 * s, y + 0.3 * s, 0.2 * s, 0, 6.2832); c.fill();
  c.fillStyle = 'rgb(255,222,90)';
  c.beginPath(); c.arc(x + 0.68 * s, y + 0.3 * s, 0.11 * s, 0, 6.2832); c.fill();
  for (var p = 0; p < 2; p++) {
    c.fillStyle = p === 0 ? 'rgb(82,150,98)' : 'rgb(34,100,76)';
    c.beginPath(); c.moveTo(x, y + s);
    for (var i = 0; i <= 20; i++) { var u = i / 20; c.lineTo(x + u * s, y + s * (p === 0 ? h1(u) : h2(u))); }
    c.lineTo(x + s, y + s); c.closePath(); c.fill();
  }
  c.restore();
  c.globalAlpha = a; c.strokeStyle = '#04204B'; c.lineWidth = 1.2; c.strokeRect(x, y, s, s); c.globalAlpha = 1;
}

function drawLatent(cx, cy, s, a, E, gridA) {
  if (a <= 0.01) return;
  var x = cx - s / 2, y = cy - s / 2, d = s * 0.055 * E;
  var tints = ['#d4c8f0', '#bfe0da', '#ecc9b8'];
  c.globalAlpha = a; c.lineWidth = 1; c.strokeStyle = '#04204B';
  for (var k = 3; k >= 1; k--) {
    c.fillStyle = tints[k - 1];
    c.fillRect(x + k * d, y - k * d, s, s);
    c.strokeRect(x + k * d, y - k * d, s, s);
  }
  var cs = s / 32;
  for (var j = 0; j < 32; j++) for (var i = 0; i < 32; i++) {
    c.fillStyle = LAT[j * 32 + i];
    c.fillRect(x + i * cs, y + j * cs, cs + 0.6, cs + 0.6);
  }
  c.strokeRect(x, y, s, s);
  if (gridA > 0.01) {
    c.globalAlpha = a * gridA * 0.8; c.strokeStyle = '#04204B'; c.lineWidth = 0.8;
    c.beginPath();
    for (var m = 1; m < 16; m++) {
      var o = m * s / 16;
      c.moveTo(x + o, y); c.lineTo(x + o, y + s);
      c.moveTo(x, y + o); c.lineTo(x + s, y + o);
    }
    c.stroke();
  }
  c.globalAlpha = 1;
}

function drawPatch(cx, cy, sz, pi, pj, a) {
  var h = sz / 2;
  c.globalAlpha = a;
  for (var b = 0; b < 2; b++) for (var q = 0; q < 2; q++) {
    c.fillStyle = LAT[(2 * pj + b) * 32 + 2 * pi + q];
    c.fillRect(cx - h + q * h, cy - h + b * h, h + 0.5, h + 0.5);
  }
  c.strokeStyle = '#0B4FC0'; c.lineWidth = 1.2;
  c.strokeRect(cx - h, cy - h, sz, sz);
  c.globalAlpha = 1;
}

var CAPS = [
  'Phase 1: a 256 × 256 colour image lives in pixel space',
  'Phase 2: the VAE encoder compresses it into a small latent',
  'Phase 3: the latent is cut into 2 × 2 patches, one token per patch',
  'Phase 4: the transformer works on tokens; the VAE decoder restores the pixels at the end'
];

return {
  draw: function (ctx, width, height, time, dt) {
    c = ctx;
    var W = width, H = height;
    c.fillStyle = '#ffffff'; c.fillRect(0, 0, W, H);
    c.textBaseline = 'alphabetic';

    var lt = time % 16, u;
    if (lt < 2) u = 0;
    else if (lt < 8.4) u = (lt - 2) / 6.4;
    else if (lt < 10.2) u = 1;
    else if (lt < 15) u = 1 - (lt - 10.2) / 4.8;
    else u = 0;
    var back = lt >= 8.4 && lt < 15;
    var E = sm((u - 0.1) / 0.28), Gp = sat((u - 0.4) / 0.1), F = sat((u - 0.52) / 0.43), tr = sm((u - 0.92) / 0.08);
    var Fs = sm(F);

    // caption (phase text at top centre)
    var ph, ps, pe;
    if (lt >= 15) { ph = 0; ps = 15; pe = 17; }
    else if (lt < 2.64) { ph = 0; ps = -1; pe = 2.64; }
    else if (lt < 4.56) { ph = 1; ps = 2.64; pe = 4.56; }
    else if (lt < 8.4) { ph = 2; ps = 4.56; pe = 8.4; }
    else { ph = 3; ps = 8.4; pe = 15; }
    var ca = sm((lt - ps) / 0.35) * sm((pe - lt) / 0.3);
    c.font = '13px sans-serif';
    var lines = wrap(CAPS[ph], W - 20);
    for (var li = 0; li < lines.length; li++) {
      txt(lines[li], W / 2, lines.length === 1 ? 24 : 19 + li * 16, '#04204B', ca, 'center', 13, false);
    }

    // layout
    var cy = H * 0.295;
    var span = Math.min(W * 0.3, 260);
    var imgS = Math.min(130, W * 0.28), latS = imgS * 0.62;
    var imgX = W / 2 - span, latX = W / 2 + span, tcx = W / 2;
    var gap = (latX - latS / 2) - (imgX + imgS / 2);
    var tw = Math.min(gap - 24, 220);
    var nameY = cy + imgS / 2 + 16;

    // encoder / decoder trapezoid
    var ta = 0.3 + 0.7 * sat(Math.sin(Math.PI * E) * 1.6);
    var hl = imgS * 0.9, hr = latS * 0.9;
    c.globalAlpha = ta * 0.55; c.fillStyle = '#DCE7FA';
    c.beginPath();
    c.moveTo(tcx - tw / 2, cy - hl / 2); c.lineTo(tcx + tw / 2, cy - hr / 2);
    c.lineTo(tcx + tw / 2, cy + hr / 2); c.lineTo(tcx - tw / 2, cy + hl / 2); c.closePath(); c.fill();
    c.globalAlpha = ta; c.strokeStyle = '#0B4FC0'; c.lineWidth = 1.4; c.stroke(); c.globalAlpha = 1;
    txt(back ? 'VAE decoder' : 'VAE encoder', tcx, cy + 4, '#04204B', 0.45 + 0.55 * ta, 'center', 12, true);
    // direction arrow
    var ax0 = tcx - tw * 0.3, ax1 = tcx + tw * 0.3, ay = cy + imgS / 2 + 10;
    if (back) { var tmp = ax0; ax0 = ax1; ax1 = tmp; }
    var dir = back ? -1 : 1;
    c.strokeStyle = '#3D5F91'; c.fillStyle = '#3D5F91'; c.lineWidth = 1.4;
    c.beginPath(); c.moveTo(ax0, ay); c.lineTo(ax1, ay); c.stroke();
    c.beginPath(); c.moveTo(ax1, ay); c.lineTo(ax1 - dir * 7, ay - 4); c.lineTo(ax1 - dir * 7, ay + 4); c.closePath(); c.fill();

    // original image (ghosted once copied)
    drawImg(imgX, cy, imgS, 1 - 0.72 * E);
    txt('image x', imgX, nameY, '#3D5F91', 1, 'center', 12, false);
    // travelling copy: image -> latent
    var mx = lerp(imgX, latX, E), ms = lerp(imgS, latS, E);
    if (E > 0.001) {
      drawImg(mx, cy, ms, 1 - E);
      drawLatent(mx, cy, ms, E * (1 - 0.55 * Fs), E, Gp);
    }
    txt('latent z', latX, nameY, '#3D5F91', E, 'center', 12, false);

    // stage labels
    var ly = H * 0.575;
    var a1 = sat(1 - E * 2.2), a2 = sat((E - 0.55) * 3) * sat(1 - F * 5), a3 = sat((F - 0.2) * 4);
    txt('image 3 × 256 × 256 = 196,608 numbers', W / 2, ly, '#04204B', a1, 'center', 13, true);
    txt('pixel space: every pixel carries R, G, B', W / 2, ly + 18, '#3D5F91', a1, 'center', 12, false);
    txt('latent 4 × 32 × 32 = 4,096 numbers (÷48)', W / 2, ly, '#0B4FC0', a2, 'center', 13, true);
    txt('latent space: 4 channels on a 32 × 32 grid', W / 2, ly + 18, '#3D5F91', a2, 'center', 12, false);
    txt('2 × 2 patches: 16 × 16 = 256 tokens', W / 2, ly, '#B4552F', a3, 'center', 13, true);
    txt('each token = one 2 × 2 × 4 = 16-number patch', W / 2, ly + 18, '#3D5F91', a3, 'center', 12, false);

    // tokens
    var n = W < 520 ? 10 : 20;
    var slot = Math.min(40, (W - 24) / (n + 2)), tile = Math.min(34, slot * 0.78);
    var x0 = W / 2 - slot * (n + 2) / 2, tokY = H * 0.7;
    var pCell = latS / 16;
    for (var k = 0; k <= n; k++) {
      var last = k === n;
      var pi = last ? 15 : (k * 5 + 2) % 16, pj = last ? 15 : (k * 7 + 3) % 16;
      var si = last ? n + 1 : k;
      var tx = x0 + slot * (si + 0.5), ty = tokY;
      var sx = latX - latS / 2 + (pi + 0.5) * pCell, sy = cy - latS / 2 + (pj + 0.5) * pCell;
      var st = k / (n + 1) * 0.45;
      var fk = sm((F - st) / 0.55);
      if (F > 0 && fk < 1) {
        c.globalAlpha = (1 - fk) * sat(F * 10); c.strokeStyle = '#0B4FC0'; c.lineWidth = 1.3;
        c.strokeRect(sx - pCell / 2, sy - pCell / 2, pCell, pCell); c.globalAlpha = 1;
      }
      if (fk > 0.001) {
        var px = lerp(sx, tx, fk) + Math.sin(Math.PI * fk) * (k % 2 ? 22 : -22);
        var py = lerp(sy, ty, fk);
        drawPatch(px, py, lerp(pCell, tile, fk), pi, pj, 1);
        txt(last ? '256' : String(k + 1), tx, tokY + 17 + 13, '#3D5F91', sm((fk - 0.7) / 0.3), 'center', 11, false);
      }
    }
    var ea = sm((F - 0.5) / 0.4);
    c.fillStyle = '#3D5F91';
    for (var d = -1; d <= 1; d++) {
      c.globalAlpha = ea; c.beginPath(); c.arc(x0 + slot * (n + 0.5) + d * slot * 0.22, tokY, 2, 0, 6.2832); c.fill();
    }
    c.globalAlpha = 1;
    var ba = sm((F - 0.75) / 0.25);
    if (ba > 0.01) {
      var bx0 = x0 + 2, bx1 = x0 + slot * (n + 2) - 2, by = tokY + 17 + 19;
      c.globalAlpha = ba; c.strokeStyle = '#8098BC'; c.lineWidth = 1.2;
      c.beginPath(); c.moveTo(bx0, by - 4); c.lineTo(bx0, by); c.lineTo(bx1, by); c.lineTo(bx1, by - 4); c.stroke();
      c.globalAlpha = 1;
      txt('256 tokens', W / 2, by + 15, '#B4552F', ba, 'center', 12, true);
    }

    // transformer bar
    if (tr > 0.01) {
      var barY = H * 0.865, barX = x0, barW = slot * (n + 2);
      c.globalAlpha = tr; c.fillStyle = '#E8EFFB'; c.fillRect(barX, barY, barW, 26);
      c.strokeStyle = '#0B4FC0'; c.lineWidth = 1.4; c.strokeRect(barX, barY, barW, 26); c.globalAlpha = 1;
      var pulse = 0.6 + 0.4 * Math.sin(time * 4);
      c.strokeStyle = '#0B4FC0'; c.lineWidth = 1;
      for (var q = 0; q <= n + 1; q++) {
        if (q === n) continue;
        var qx = x0 + slot * (q + 0.5);
        c.globalAlpha = tr * 0.5 * pulse; c.beginPath(); c.moveTo(qx, tokY + 17 + 40); c.lineTo(qx, barY); c.stroke();
      }
      c.globalAlpha = 1;
      txt('Transformer on 256 tokens', W / 2, barY + 17, '#04204B', tr, 'center', 12, true);
    }
  }
};
